            DOM  = BeautifulSoup(html, "html5lib", from_encoding='utf-8')

            # Get list of courses
            content = DOM.find_all("div",{"class":"course-box-wrapper"})
            for wrapper in content:
                courses["content"].append(str(wrapper))
                courses["nb_courses"] += 1

            return courses

